mapper.update:
UPDATE funding
SET view_count = view_count + 1
WHERE funding_id = #{fundingId}

mapper.select:
SELECT COUNT(*)
FROM funding_like
WHERE funding_id = #{fundingId}
  AND user_id = #{userId}
    LIMIT 1

mapper.delete:
DELETE FROM funding_like
WHERE funding_id = #{fundingId}
  AND user_id = #{userId}
